package verification

const vmReportDriver = "\nvar avReportFixtureExpected *av.Binding\n\ntype avReportFixtureOptions struct {\n    Action string `json:\"action\"`\n    Report string `json:\"report\"`\n    Job string `json:\"job\"`\n    Binding string `json:\"binding\"`\n    State string `json:\"state\"`\n    Input string `json:\"input\"`\n    InvalidReport string `json:\"invalid_report\"`\n    Cancel bool `json:\"cancel\"`\n}\n\nfunc avReportFixtureCopy(source, destination string) error {\n    body, err := os.ReadFile(source)\n    if err != nil { return err }\n    file, err := os.OpenFile(destination, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)\n    if err != nil { return err }\n    _, err = file.Write(body)\n    if err == nil { err = syncFile(file) }\n    closed := file.Close()\n    if err != nil { return err }; if closed != nil { return closed }\n    return syncDirectory(filepath.Dir(destination))\n}\n\nfunc RunAVReportFixture(path string) error {\n    body, err := os.ReadFile(path)\n    var options avReportFixtureOptions\n    if err != nil || strictJSON(body, &options) != nil { return failure(\"FIXTURE_OPTIONS_INVALID\",400) }\n    body, err = os.ReadFile(options.Job)\n    var job Job\n    if err != nil || strictJSON(body, &job) != nil || job.JobID != \"job_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\" || job.AttemptID != \"attempt_bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb\" || job.InputReceipt == nil { return failure(\"FIXTURE_JOB_INVALID\",400) }\n    if options.Binding != \"\" {\n        body, err = os.ReadFile(options.Binding)\n        var binding av.Binding\n        if err != nil || strictJSON(body, &binding) != nil { return failure(\"FIXTURE_BINDING_INVALID\",400) }\n        avReportFixtureExpected = &binding\n    }\n    if options.Action == \"decode\" {\n        report, digest, decodeErr := decodeReport(options.Report, job, nil)\n        code := \"\"; if decodeErr != nil { code = errorReason(decodeErr) }\n        return json.NewEncoder(os.Stdout).Encode(map[string]any{\"accepted\":decodeErr==nil,\"error\":code,\"report_sha256\":digest,\"validation\":report.avValidation,\"stage0_passed\":Stage0Passed})\n    }\n    if options.Action != \"seed-crash\" && options.Action != \"reopen\" && options.Action != \"settle\" { return failure(\"FIXTURE_ACTION_INVALID\",400) }\n    b, err := Open(Config{DataDir:options.State})\n    if err != nil { return err }\n    defer b.Close()\n    ctx := context.Background()\n    directory := filepath.Join(options.State,\"runtime\",job.AttemptID)\n    run := &scanRun{job:job,directory:directory,stopped:make(chan struct{}),accepted:make(chan struct{},1)}\n    if options.Action == \"seed-crash\" {\n        // These rows model a report boundary only; no VM or scanner is launched.\n        if privateDirectory(filepath.Join(directory,\"output\")) != nil { return storageError() }\n        original := filepath.Join(options.State,\"objects\",job.InputReceipt.ObjectID)\n        if avReportFixtureCopy(options.Input,original) != nil || os.Chmod(original,0400) != nil || b.verifyObject(original,job.InputReceipt.SHA256,job.InputReceipt.ByteSize) != nil { return failure(\"FIXTURE_INPUT_INVALID\",400) }\n        tx, err := b.db.BeginTx(ctx,nil)\n        if err != nil { return err }; defer tx.Rollback()\n        if _,err=tx.Exec(\"INSERT INTO jobs(id,created,data) VALUES(?,?,?)\",job.JobID,time.Now().UnixNano(),encode(job)); err!=nil{return err}\n        if _,err=tx.Exec(\"INSERT INTO attempts(id,job_id,data) VALUES(?,?,?)\",job.AttemptID,job.JobID,encode(job)); err!=nil{return err}\n        if _,err=tx.Exec(\"INSERT INTO objects(id,job_id,sha256,size,available) VALUES(?,?,?,?,1)\",job.InputReceipt.ObjectID,job.JobID,job.InputReceipt.SHA256,job.InputReceipt.ByteSize); err!=nil{return err}\n        if _,err=tx.Exec(\"INSERT INTO runtime_runs(attempt_id,job_id,state,directory,raw_reserved,report_reserved,control_reserved) VALUES(?,?,'INSPECTING',?,?,?,?)\",job.AttemptID,job.JobID,directory,rawReservation,reportLimit,controlReservation); err!=nil{return err}\n        if _,err=tx.Exec(\"INSERT INTO resource_pins(owner_id,object_id) VALUES(?,?)\",job.AttemptID,job.InputReceipt.ObjectID);err!=nil{return err}\n        if _,err=tx.Exec(\"INSERT INTO scan_queue(job_id,attempt_id) VALUES(?,?)\",job.JobID,job.AttemptID);err!=nil{return err}\n        if err=tx.Commit();err!=nil{return err}\n        reportPath:=filepath.Join(directory,\"output\",\"report.json\")\n        if err=avReportFixtureCopy(options.Report,reportPath);err!=nil{return err}\n        _,digest,err:=b.acceptReport(run)\n        if err!=nil{return err}\n        accepted,err:=readJob(ctx,b.db,job.JobID)\n        if err!=nil{return err}\n        invalidCode:=\"\"\n        if options.InvalidReport!=\"\" {\n            if err=os.Remove(reportPath);err!=nil{return err}\n            if err=avReportFixtureCopy(options.InvalidReport,reportPath);err!=nil{return err}\n            _,_,invalidErr:=b.acceptReport(run)\n            if invalidErr==nil{return failure(\"FIXTURE_INVALID_REPORT_ACCEPTED\",409)}\n            invalidCode=errorReason(invalidErr)\n            after,err:=readJob(ctx,b.db,job.JobID)\n            if err!=nil || !bytes.Equal(encode(accepted),encode(after)){return failure(\"FIXTURE_REJECTION_CHANGED_JOB\",409)}\n        }\n        if options.Cancel {\n            b.mu.Lock(); b.scanActive=run; b.mu.Unlock()\n            if _,err=b.Cancel(ctx,job.JobID);err!=nil{return err}\n            b.mu.Lock(); b.scanActive=nil; b.mu.Unlock()\n        }\n        if err=json.NewEncoder(os.Stdout).Encode(map[string]any{\"accepted\":true,\"report_sha256\":digest,\"job\":accepted,\"invalid_report_error\":invalidCode,\"cancel_requested\":options.Cancel,\"stage0_passed\":Stage0Passed});err!=nil{return err}\n        os.Exit(91)\n    }\n    if options.Action==\"settle\" {\n        b.mu.Lock()\n        // Synthetic reservation settlement is not evidence of VM stop or raw deletion.\n        err=b.finishScanLocked(run,nil,\"\",true)\n        b.mu.Unlock()\n        if err!=nil{return err}\n    }\n    current,err:=readJob(ctx,b.db,job.JobID)\n    if err!=nil{return err}\n    closeErr:=b.Close(); closeCode:=\"\"\n    if closeErr!=nil{closeCode=errorReason(closeErr)}\n    return json.NewEncoder(os.Stdout).Encode(map[string]any{\"job\":current,\"close_error\":closeCode,\"stage0_passed\":Stage0Passed})\n}"
